"""Module with main procedure of pcap flow verification."""

import logging
from pathlib import Path
from pprint import pformat
from typing import List, Union
from dataclasses import dataclass, field
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import AbstractInspector, InspectionError
from taf.rfrl.utilities.parsers.pcap_checker.utils import AbstractPcapProvider, PACKET
from taf.rfrl.utilities.parsers.pcap_checker.exceptions import MessageNotFoundError, VerificationError, FoundError


@dataclass
class AwaitedMessage:
    """Expected message defined by user."""

    name: str
    find_by: List[AbstractInspector]
    verify_by: List[AbstractInspector] = field(default_factory=list)


@dataclass
class AwaitingStatus:
    """Status of founding message in packets flow."""

    is_found: bool = field(default=False)
    is_verified: bool = field(default=False)
    error: str = field(default='')


@dataclass
class MessageMatcher:
    """Verifier to check if packet match to given message."""

    message: AwaitedMessage
    status: AwaitingStatus = field(default_factory=AwaitingStatus)
    packet: PACKET = field(default=None)

    def match(self, packet: PACKET) -> None:
        """Matches given packet to message. Result of matching is stored in status attribute."""

        find_error = self.inspect(packet, self.message.find_by)

        if find_error == '' and len(self.message.verify_by) > 0:
            verify_error = self.inspect(packet, self.message.verify_by)
        else:
            verify_error = ''

        self.status.is_found = not find_error
        self.status.is_verified = not verify_error
        self.status.error = find_error if not verify_error else verify_error

        if self.status.is_found:
            self.packet = packet

    @staticmethod
    def inspect(packet, inspectors):
        """Checks if given inspectors passes for given packet."""

        error_message = ''

        for inspector in inspectors:

            try:
                inspector.inspect(packet)
            except InspectionError as error:
                error_message += f'{error}; '

        return error_message


class Checker:
    """Checks content of given pcap file with given pattern."""

    def __init__(self, pcap_provider: AbstractPcapProvider) -> None:
        self.pcap_provider = pcap_provider

    def expect_flow(self, pcap_file: Union[str, Path], display_filter: str,
                    awaited_messages: List[AwaitedMessage], forbidden_messages: List[AwaitedMessage]) -> None:
        """
        Expects given flow of messages in awaited messages pcap file.
        If there are some forbidden messages and one of them will be matched the verification will fail.
        """

        packets = self._get_packets(pcap_file, display_filter)

        logging.info(f"awaited_messages:\n{pformat(awaited_messages)}")
        logging.info(f"forbidden_messages:\n{pformat(forbidden_messages)}")
        awaited_message_matchers = [MessageMatcher(message) for message in awaited_messages]
        forbidden_message_matchers = [MessageMatcher(message) for message in forbidden_messages]

        awaited_message_matcher_index = 0
        number_of_awaited_message_matchers = len(awaited_message_matchers)

        for packet in packets:

            for forbidden_message_matcher in forbidden_message_matchers:
                forbidden_message_matcher.match(packet)
                self._verify_matching_status_of_single_forbidden_message(forbidden_message_matcher)

            if awaited_message_matcher_index >= number_of_awaited_message_matchers:
                continue

            awaited_message_matcher = awaited_message_matchers[awaited_message_matcher_index]
            awaited_message_matcher.match(packet)

            if awaited_message_matcher.status.is_found:
                awaited_message_matcher_index += 1

        self._verify_matching_status_of_awaited_messages(awaited_message_matchers)

    def get_packets(self, pcap_file: Union[str, Path], display_filter: str,
                    awaited_message: AwaitedMessage) -> List[PACKET]:
        """Gets all packets matched by given message definition."""

        packets = self._get_packets(pcap_file, display_filter)
        matcher = MessageMatcher(awaited_message)

        if len(matcher.message.verify_by) != 0:
            logging.warning('"verify_by" section is ignored in current use cases')

        matched_packets = []

        for packet in packets:
            matcher.match(packet)

            if matcher.status.is_found:
                matched_packets.append(packet)

        return matched_packets

    def count_packets(self, pcap_file: Union[str, Path], display_filter: str, awaited_message: AwaitedMessage) -> int:
        """Counts all packets matched by given message definition."""

        packets = self.get_packets(pcap_file, display_filter, awaited_message)
        return len(packets)

    def _get_packets(self, pcap_file: Union[str, Path], display_filter: str):
        """Gets packets from pcap analyzer object."""

        pcap_provider = self.pcap_provider.setup(pcap_file, display_filter)
        return pcap_provider.get_packets()

    @staticmethod
    def _verify_matching_status_of_awaited_messages(matchers: List[MessageMatcher]) -> None:
        """Verifies statuses of matching awaited messages by matchers."""

        for matcher in matchers:

            if not matcher.status.is_found:
                error_message = f'Message {matcher.message.name} not found: {matcher.status.error}'
                logging.error(error_message)
                raise MessageNotFoundError(error_message)

            if not matcher.status.is_verified:
                error_message = f'Message {matcher.message.name} found but has invalid parameters: {matcher.status.error}'
                logging.error(error_message)
                raise VerificationError(error_message)

    @staticmethod
    def _verify_matching_status_of_single_forbidden_message(matcher: MessageMatcher) -> None:
        """Verifies statuses of matching forbidden messages by matchers."""

        if matcher.status.is_found:

            if matcher.status.is_verified:
                error_message = f'Forbidden message {matcher.message.name} was found.'
                logging.error(error_message)
                raise FoundError(error_message)

            logging.warning('Forbidden message %s was found but was verified unsuccessfully.', matcher.message.name)
